"""Final run report (md, html, pdf) is generated by code from the decision log at the end of a run."""
import os

import orchestrator
from conftest import TestFounder, drive, load_brief


def test_full_run_writes_report_in_three_forms(env, fake_llm, fake_sources):
    b, pre = load_brief("r")
    ctx = orchestrator.new_run(b, "q")
    drive(ctx, TestFounder(pre))
    md = open(env / "outputs" / "phase6_step9_run_report_q_a1.md", encoding="utf-8").read()
    assert "Phase 6 of 6" in md and "| 1 · Discover | `go` | continue |" in md
    assert "$0.00" in md and "MOCKED" in md and "UNVALIDATED · FOUNDER OVERRIDE" in md
    html = open(env / "outputs" / "phase6_step9_run_report_q_a1.html", encoding="utf-8").read()
    assert html.startswith("<!DOCTYPE html>") and "Gates and founder decisions" in html
    pdf = ctx.data.get("report_pdf")
    if pdf:                                   # reportlab installed
        assert os.path.getsize(pdf) > 2000 and open(pdf, "rb").read(4) == b"%PDF"


def test_excluded_run_report_shows_the_stop(env, fake_llm, fake_sources):
    b, _ = load_brief("e")
    ctx = orchestrator.new_run(b, "x")
    orchestrator.run_until_gate(ctx)
    md = open(env / "outputs" / "phase1_step9_run_report_x_a1.md", encoding="utf-8").read()
    assert "Stop" in md and "Excluded product category" in md and "Phase 1 of 6" in md
